using System.Text.Json;using QualityReporter.CSharp;using QualityReporter.CSharp.Analysis;using QualityReporter.CSharp.Coverage;using QualityReporter.CSharp.Git;using QualityReporter.CSharp.Duplication;using QualityReporter.CSharp.Metrics;using QualityReporter.CSharp.Reporting;using QualityReporter.CSharp.SymbolExtraction;
if(args.Length==0||args[0]!="analyze"){Console.Error.WriteLine("Usage: quality-csharp analyze (--solution <path> | --project <path>) --output <path> [--coverage file] [--analyzer file] [--duplication file] [--config file] [--baseline file] [--markdown file] [--since 180d]");return 2;}var o=new Dictionary<string,string>();for(var i=1;i<args.Length;i+=2)if(i+1<args.Length)o[args[i]]=args[i+1];var hasSolution=o.TryGetValue("--solution",out var solution);var hasProject=o.TryGetValue("--project",out var project);if(hasSolution==hasProject||!o.TryGetValue("--output",out var output)){Console.Error.WriteLine("Exactly one of --solution or --project, and --output, are required");return 2;}var input=hasSolution?solution!:project!;if(!File.Exists(input)){Console.Error.WriteLine($"{(hasSolution?"Solution":"Project")} not found: {input}");return 2;}try{var analysisRoot=Path.GetDirectoryName(Path.GetFullPath(input))!;var cfg=o.TryGetValue("--config",out var cp)?JsonSerializer.Deserialize<Config>(File.ReadAllText(cp),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??new():new Config();var days=o.TryGetValue("--since",out var since)&&int.TryParse(since.TrimEnd('d'),out var d)?d:cfg.HistoryDays;var git=new GitCommandRunner();var repositoryRoot=Path.GetFullPath(git.Run(analysisRoot,"rev-parse","--show-toplevel").Trim());var (history,couplings)=new GitHistoryAnalyzer(git).Analyze(repositoryRoot,days,cfg);var files=SourceFileDiscovery.Discover(analysisRoot,repositoryRoot,cfg);var metrics=new CodeMetricsAnalyzer();var extractor=new CSharpSymbolExtractor(cfg.MethodAnalysis);var results=files.Select(f=>{var(m,fn)=metrics.Analyze(f.AbsolutePath);return new FileResult{Path=f.RepositoryPath,Metrics=m,Functions=fn,Symbols=cfg.MethodAnalysis.Enabled?extractor.Extract(f.RepositoryPath,File.ReadAllText(f.AbsolutePath)).ToList():[],History=history.GetValueOrDefault(f.RepositoryPath)??new(),Couplings=couplings.Where(x=>x.File==f.RepositoryPath).ToList()};}).ToList();var report=new Report{Repository=new{branch=git.Run(repositoryRoot,"branch","--show-current").Trim(),commit=git.Run(repositoryRoot,"rev-parse","HEAD").Trim()},Files=results};if(o.TryGetValue("--coverage",out var cov)&&File.Exists(cov)){var data=CoberturaParser.Parse(cov);foreach(var f in results)if(data.TryGetValue(f.Path,out var c))(f.Metrics.LineCoverage,f.Metrics.BranchCoverage)=c;}else report.Warnings.Add("Coverage: Not Available");if(o.TryGetValue("--analyzer",out var an)&&File.Exists(an))foreach(var i in AnalyzerResultParser.Parse(an)){var f=results.FirstOrDefault(x=>i.File.EndsWith(x.Path));if(f!=null){if(i.Severity=="error")f.Metrics.Issues.Error++;else if(i.Severity=="warning")f.Metrics.Issues.Warning++;else f.Metrics.Issues.Info++;}}else report.Warnings.Add("Analyzer results: Not Available");ActivityCalculator.Calculate(results,cfg.ActivityWeights,cfg.FileMaturity);foreach(var f in results){var raw=UntestedComplexityCalculator.Calculate(f.Metrics.Complexity,f.Metrics.LineCoverage,f.Metrics.BranchCoverage,cfg.UntestedComplexity.CoverageMode);if(raw.HasValue)f.Metrics.UntestedComplexity=new(){Raw=raw.Value};}var duplicatePath=o.GetValueOrDefault("--duplication",Path.Combine(repositoryRoot,cfg.Duplication.ReportPath));if(cfg.Duplication.Enabled&&File.Exists(duplicatePath)){report.Duplicates=new JscpdReportParser().Parse(File.ReadAllText(duplicatePath)).Where(x=>x.Lines>=cfg.Duplication.MinimumLines&&x.Tokens>=cfg.Duplication.MinimumTokens).ToList();DuplicateSymbolMapper.Map(report.Duplicates,results);}else report.Warnings.Add("Duplication: Not Available");RiskCalculator.Calculate(results,cfg.RiskWeights,o.TryGetValue("--analyzer",out var analyzerPath)&&File.Exists(analyzerPath));HotspotPriorityCalculator.Calculate(results,cfg.FileMaturity);QualityScoresCalculator.Calculate(results,cfg);HotspotClassifier.Classify(results,cfg);RecommendationEngine.Generate(results);report.Summary=new{files=results.Count,qualityAxes=new{maintainability=AxisSummary(results.Select(x=>x.Scores.Maintainability.Score)),testability=AxisSummary(results.Select(x=>x.Scores.Testability.Score)),architecture=AxisSummary(results.Select(x=>x.Scores.Architecture.Score))},activity=new{high=results.Count(x=>x.Activity.EffectiveScore>=70),medium=results.Count(x=>x.Activity.EffectiveScore>=40&&x.Activity.EffectiveScore<70),low=results.Count(x=>x.Activity.EffectiveScore<40)},risk=new{critical=results.Count(x=>x.Risk.Level=="critical"),high=results.Count(x=>x.Risk.Level=="high"),medium=results.Count(x=>x.Risk.Level=="medium"),low=results.Count(x=>x.Risk.Level=="low")},classification=new{active=results.Count(x=>x.Hotspot.Classifications.Contains("active")),newActive=results.Count(x=>x.Hotspot.Classifications.Contains("new_active")),complex=results.Count(x=>x.Hotspot.Classifications.Contains("complex")),rework=results.Count(x=>x.Hotspot.Classifications.Contains("rework")),untested=results.Count(x=>x.Hotspot.Classifications.Contains("untested")),coupled=results.Count(x=>x.Hotspot.Classifications.Contains("coupled")),critical=results.Count(x=>x.Hotspot.Classifications.Contains("critical"))},overallRisk=results.Count==0?0:results.Average(x=>x.Risk.Score),hotspotCount=results.Count(x=>(x.Scores.HotspotPriority.Score??x.Hotspot.PriorityScore)>=60),criticalCount=results.Count(x=>x.Risk.Level=="critical"),averageCoverage=results.Where(x=>x.Metrics.LineCoverage.HasValue).Select(x=>x.Metrics.LineCoverage).DefaultIfEmpty().Average(),averageComplexity=results.Count==0?0:results.Average(x=>x.Metrics.Complexity),highComplexityFunctionCount=results.SelectMany(x=>x.Functions).Count(x=>x.Complexity>=15)};if(o.TryGetValue("--baseline",out var baseline)&&File.Exists(baseline))report.Trend=BaselineComparer.Compare(report,ReportWriter.Read(baseline));ReportWriter.WriteJson(report,output);if(o.TryGetValue("--markdown",out var md))ReportWriter.WriteMarkdown(report,md);Console.WriteLine($"Analyzed {results.Count} C# files; report: {output}");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}

static object AxisSummary(IEnumerable<double?> input){var v=input.Where(x=>x.HasValue).Select(x=>x!.Value).Order().ToArray();double? Pick(double p)=>v.Length==0?null:v[(int)Math.Ceiling((v.Length-1)*p)];return new{median=Pick(.5),p90=Pick(.9),criticalCount=v.Count(x=>x>=80),highCount=v.Count(x=>x>=60&&x<80)};}
